import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation, gql } from '@apollo/client';
import { useAuth } from '../../context/AuthContext';
import './Login.css';

const LOGIN_MUTATION = gql`
  mutation Login($email: String!, $password: String!) {
    login(email: $email, password: $password) {
      token
      user {
        id
        username
        email
        role
        scopes
      }
    }
  }
`;

const Login = () => {
  const [loginInput, setLoginInput] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [fieldErrors, setFieldErrors] = useState({ loginInput: '', password: '' });
  const { login } = useAuth();
  const navigate = useNavigate();

  const [loginMutation, { loading }] = useMutation(LOGIN_MUTATION, {
    onCompleted: (data) => {
      if (data?.login?.token && data?.login?.user) {
        login(data.login.user, data.login.token);
        navigate('/dashboard', { replace: true });
      } else {
        setError('Invalid response from server');
      }
    },
    onError: (err) => {
      if (err.networkError) {
        setError('Cannot connect to server. Please ensure the backend server is running.');
      } else {
        // Show specific error messages
        const errorMsg = err.message || 'Login failed';
        setError(errorMsg);
      }
    },
  });

  const validateField = (fieldName, value) => {
    if (fieldName === 'loginInput') {
      if (!value || value.trim() === '') {
        return 'Username or email is required';
      }
      return '';
    }
    if (fieldName === 'password') {
      if (!value || value.trim() === '') {
        return 'Password is required';
      }
      return '';
    }
    return '';
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    
    const loginInputError = validateField('loginInput', loginInput);
    const passwordError = validateField('password', password);
    
    setFieldErrors({
      loginInput: loginInputError,
      password: passwordError
    });

    if (loginInputError || passwordError) {
      return;
    }

    // Determine if input is email or username
    const isEmail = loginInput.includes('@');
    const variables = isEmail 
      ? { email: loginInput, password }
      : { username: loginInput, password };

    loginMutation({ variables });
  };

  const handleInputChange = (fieldName, value) => {
    if (fieldName === 'loginInput') {
      setLoginInput(value);
    } else if (fieldName === 'password') {
      setPassword(value);
    }
    
    // Clear error when user starts typing
    setError('');
    if (fieldErrors[fieldName]) {
      setFieldErrors(prev => ({ ...prev, [fieldName]: '' }));
    }
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <div className="login-logo-container">
            <img 
              src="https://shinelogisticsllc.com/wp-content/uploads/2023/01/Asset-109.png" 
              alt="Company Logo" 
              className="login-logo"
            />
          </div>
        </div>
        <form onSubmit={handleSubmit} className="login-form">
          {error && (
            <div className="error-message">
              <span className="error-icon">⚠️</span>
              <span className="error-text">{error}</span>
            </div>
          )}
          <div className="form-group">
            <label htmlFor="loginInput">Username or Email</label>
            <input
              id="loginInput"
              type="text"
              value={loginInput}
              onChange={(e) => handleInputChange('loginInput', e.target.value)}
              placeholder="Enter your username or email"
              className={fieldErrors.loginInput ? 'input-error' : ''}
              autoFocus
            />
            {fieldErrors.loginInput && (
              <span className="field-error-message">{fieldErrors.loginInput}</span>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => handleInputChange('password', e.target.value)}
              placeholder="Enter password"
              className={fieldErrors.password ? 'input-error' : ''}
            />
            {fieldErrors.password && (
              <span className="field-error-message">{fieldErrors.password}</span>
            )}
          </div>
          <button type="submit" className="login-button" disabled={loading}>
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;
